package dev.agentscope.starter;
import org.junit.jupiter.api.Test;
import org.springframework.boot.test.context.runner.ApplicationContextRunner;
import org.springframework.boot.autoconfigure.AutoConfigurations;
import io.micrometer.observation.*;
import org.springframework.ai.tool.observation.ToolCallingObservationContext;
import org.springframework.ai.tool.definition.ToolDefinition;
import org.mockito.ArgumentCaptor;
import java.util.*;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;
class StarterTest {
 @Test void autoConfigurationAndDisable(){var r=new ApplicationContextRunner().withConfiguration(AutoConfigurations.of(AgentScopeAutoConfiguration.class));r.run(c->assertThat(c).hasSingleBean(AgentScopeObservationHandler.class));r.withPropertyValues("agentscope.enabled=false").run(c->assertThat(c).doesNotHaveBean(TelemetryExporter.class));}
 @Test void redaction(){var r=new Redactor(List.of("private-word"));assertThat(r.clean("alice@example.com Bearer abc.def password=hello +91 98765 43210 private-word sk-abcdefghijklmnop")).doesNotContain("alice","abc.def","hello","98765","private-word","sk-abc");}
 @Test void nativeToolContextAndHierarchy(){var p=new AgentScopeProperties();p.getTracing().setCaptureInputs(true);p.getTracing().setCaptureOutputs(true);var e=mock(TelemetryExporter.class);var registry=ObservationRegistry.create();registry.observationConfig().observationHandler(new AgentScopeObservationHandler(p,e,new Redactor(List.of())));Observation.createNotStarted("spring.ai.chat.client",registry).observe(()->{var tc=ToolCallingObservationContext.builder().toolDefinition(ToolDefinition.builder().name("searchFlights").description("Search").inputSchema("{}").build()).toolCallArguments("alice@example.com").build();Observation.createNotStarted("spring.ai.tool",()->tc,registry).observe(()->tc.setToolCallResult("found"));});var cap=ArgumentCaptor.forClass(SpanData.class);verify(e,times(2)).offer(cap.capture());var child=cap.getAllValues().get(0);var parent=cap.getAllValues().get(1);assertThat(child.traceId()).isEqualTo(parent.traceId());assertThat(child.parentSpanId()).isEqualTo(parent.spanId());assertThat(child.name()).isEqualTo("searchFlights");assertThat(child.input()).isEqualTo("[REDACTED]");assertThat(child.output()).isEqualTo("found");}
 @Test void noContentByDefault(){var p=new AgentScopeProperties();var e=mock(TelemetryExporter.class);var h=new AgentScopeObservationHandler(p,e,new Redactor(List.of()));var c=ToolCallingObservationContext.builder().toolDefinition(ToolDefinition.builder().name("test").description("test").inputSchema("{}").build()).toolCallArguments("secret").toolCallResult("private").build();c.setName("spring.ai.tool");h.onStart(c);h.onStop(c);var cap=ArgumentCaptor.forClass(SpanData.class);verify(e).offer(cap.capture());assertThat(cap.getValue().input()).isNull();assertThat(cap.getValue().output()).isNull();}
 @Test void exporterDeliversAndBackpressureIsNonBlocking() throws Exception {var server=com.sun.net.httpserver.HttpServer.create(new java.net.InetSocketAddress("127.0.0.1",0),0);var count=new java.util.concurrent.atomic.AtomicInteger();server.createContext("/api/v1/traces",x->{count.incrementAndGet();x.sendResponseHeaders(202,-1);x.close();});server.start();var p=new AgentScopeProperties();p.setEndpoint("http://127.0.0.1:"+server.getAddress().getPort());p.setQueueCapacity(2);var s=new SpanData("a".repeat(32),"b".repeat(16),null,"test","test","AGENT",java.time.Instant.now(),1,"SUCCESS",null,null,null,null,0,0,0,Map.of());try(var e=new TelemetryExporter(p,new com.fasterxml.jackson.databind.ObjectMapper())){e.offer(s);long end=System.currentTimeMillis()+4000;while(e.delivered.get()==0&&System.currentTimeMillis()<end)Thread.sleep(20);assertThat(e.delivered.get()).isEqualTo(1);assertThat(count.get()).isEqualTo(1);}finally{server.stop(0);}p.setEndpoint("http://127.0.0.1:1");try(var e=new TelemetryExporter(p,new com.fasterxml.jackson.databind.ObjectMapper())){long start=System.nanoTime();for(int i=0;i<1000;i++)e.offer(s);assertThat((System.nanoTime()-start)/1e6).isLessThan(500);assertThat(e.dropped.get()).isPositive();}}
}